__global__ void matmul_kernel(const float* __restrict__ A, 
                             const float* __restrict__ B, 
                             float* __restrict__ C, 
                             int N) {
    // Shared memory for double buffering
    __shared__ float sA[2][BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float sB[2][BLOCK_SIZE][BLOCK_SIZE];

    // Thread coordinates
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Block coordinates
    int blockRow = blockIdx.y * TILE_SIZE;
    int blockCol = blockIdx.x * TILE_SIZE;

    // Register storage for results
    float c[TILE_SIZE][TILE_SIZE] = {{0.0f}};

    // Buffering indices
    int buffer = 0;
    int next_buffer = 1;

    // Prefetch first tile
    int t = 0;
    int tiled_col = t * BLOCK_SIZE + tx;
    int tiled_row = t * BLOCK_SIZE + ty;

    sA[buffer][ty][tx] = (blockRow + ty < N && tiled_col < N) ? A[(blockRow + ty) * N + tiled_col] : 0.0f;
    sB[buffer][ty][tx] = (tiled_row < N && blockCol + tx < N) ? B[tiled_row * N + (blockCol + tx)] : 0.0f;

    __syncthreads();

    // Loop over tiles
    for (t = 0; t < (N + BLOCK_SIZE - 1) / BLOCK_SIZE; t++) {
        // Prefetch next tile
        int next_t = t + 1;
        int next_tiled_col = next_t * BLOCK_SIZE + tx;
        int next_tiled_row = next_t * BLOCK_SIZE + ty;

        if (next_t < (N + BLOCK_SIZE - 1) / BLOCK_SIZE) {
